"""Response and turn-result payloads exchanged across the orchestration boundary.

These are the plain-data types the ``SkillExecutor`` returns to the
``Orchestrator`` (``AgentResponse``) and the ``Orchestrator`` returns to the
message processor (``TurnResult``).  The structural interfaces that consume
them live in :mod:`rasa.mantle.orchestration.contracts`.
"""

from __future__ import annotations

from enum import Enum
from typing import TYPE_CHECKING, Any, Callable, Optional, Union

from pydantic import BaseModel, ConfigDict, Field

from rasa.mantle.content.responses import ResponseButton

if TYPE_CHECKING:
    from rasa.mantle.state.tracker_handle import TrackerHandle


class ResponseMode(str, Enum):
    """Controls whether the orchestrator loop continues after an agent response."""

    WAIT = "wait"
    """Emit the response and pause the turn — do not call the LLM again."""

    CONTINUE = "continue"
    """Emit the response and continue the iteration loop (LLM may act next)."""


class NaturalRephrase(BaseModel):
    """Generic natural-language rephrase of the canned ``text``."""

    model_config = ConfigDict(frozen=True)


class ConfirmRephrase(BaseModel):
    """Confirmation rephrase: acknowledge a known value, then ask to confirm."""

    model_config = ConfigDict(frozen=True)

    field: str
    value: Any
    field_description: Optional[str] = None


Rephrase = Union[NaturalRephrase, ConfirmRephrase]

REPHRASE_KIND_NONE = "none"
REPHRASE_KIND_NATURAL = "natural"
REPHRASE_KIND_CONFIRM = "confirm"


def rephrase_kind_label(rephrase: Optional[Rephrase]) -> str:
    """Return an observability label for *rephrase*."""
    if rephrase is None:
        return REPHRASE_KIND_NONE
    if isinstance(rephrase, ConfirmRephrase):
        return REPHRASE_KIND_CONFIRM
    return REPHRASE_KIND_NATURAL


class ResolvedUtterance(BaseModel):
    """Named-response lookup result with rendered text and button configuration.

    Memory placeholders in ``text``, button titles, and payloads are
    substituted at resolve time. A button source is expanded later at the
    asynchronous delivery seam.
    """

    model_config = ConfigDict(frozen=True)

    text: str
    rephrase: Optional[Rephrase] = None
    buttons: tuple[ResponseButton, ...] = Field(default_factory=tuple)
    button_source: Optional[str] = None
    """Local tool that supplies buttons at delivery time."""
    variant_metadata: dict[str, Any] = Field(default_factory=dict)
    """Authoring metadata from the selected response variant."""


ResolveUtteranceFunc = Callable[[str, "TrackerHandle"], ResolvedUtterance]


class AgentResponse(BaseModel):
    """An agent response produced by a deterministic phase.

    Returned by ``SkillExecutor.advance_steps`` when a phase emits a
    response before the LLM is invoked.  The orchestrator decides whether to
    break the loop (WAIT) or proceed with the next LLM iteration (CONTINUE).

    When ``rephrase`` is set the text is not emitted verbatim.  Instead the
    orchestrator runs a tool-free LLM rephrase call — either a
    :class:`NaturalRephrase` (generic rewrite) or a :class:`ConfirmRephrase`
    (acknowledge a prefilled collect value, then ask to confirm).  On LLM
    failure or empty output the orchestrator falls back to the canned ask text
    so the confirmation gate is preserved for confirm rephrases.
    """

    model_config = ConfigDict(frozen=True)

    text: str
    mode: ResponseMode = ResponseMode.WAIT
    rephrase: Optional[Rephrase] = None
    """``None`` emits ``text`` verbatim; otherwise selects the rephrase path."""
    response_name: Optional[str] = None
    """Name of the verbatim response template the text came from
    (``utter_*``), or ``None`` for text without a template. Carried onto the
    ``BotUttered`` metadata for observability (the Inspector's response
    provenance)."""

    completes_current_step: bool = False
    """``True`` when the producing step was intentionally not advanced yet:
    the orchestrator delivers the text first, then calls
    ``SkillExecutor.complete_delivered_step`` so completion events land
    *after* the ``BotUttered`` on the tracker (authored order). ``mode`` is
    meaningless on such responses — the executor returns the real mode from
    ``complete_delivered_step`` once the stack state after completion is
    known."""

    buttons: tuple[ResponseButton, ...] = Field(default_factory=tuple)
    """Resolved static or source-provided buttons for this response."""

    button_source: Optional[str] = None
    """Local tool that supplies buttons before this response is delivered."""

    button_source_skill_id: Optional[str] = None
    """Skill that owned ``button_source`` when this response was produced.

    Queued activate / ``when:`` / tool-outcome utters can be delivered after
    that skill has left the stack. Expand uses this instead of the live
    ``memory_scope()``.
    """

    button_source_flow_id: Optional[str] = None
    """Flow paired with ``button_source_skill_id`` for ``ToolContext`` memory."""

    variant_metadata: dict[str, Any] = Field(default_factory=dict)
    """Authoring metadata from the selected response variant."""


def button_source_scope_fields(
    button_source: Optional[str],
    skill_id: str,
    flow_id: str,
) -> dict[str, Optional[str]]:
    """Return ``AgentResponse`` kwargs that pin ``buttons.source`` to a skill.

    Empty when *button_source* is unset so callers can ``**`` this into
    :class:`AgentResponse` without stamping unused fields.
    """
    if not button_source:
        return {}
    return {
        "button_source_skill_id": skill_id or None,
        "button_source_flow_id": flow_id or None,
    }


class TurnResult(BaseModel):
    """Outcome of one completed engine turn.

    Returned by ``Orchestrator.run_turn`` to ``MessageProcessor`` after the
    full LLM iteration loop completes.  Text delivery to the output channel
    is **not** carried here — the orchestrator streams every agent response
    immediately via the ambient ``MessageTurnContext`` (``send``) established
    for the turn.
    """

    model_config = ConfigDict(frozen=True)

    error: Optional[str] = None
    """Human-readable error description when the turn failed (LLM timeout,
    max-iterations exceeded, etc.)."""

    iteration_count: int = 0
    """Number of LLM calls made during this turn (for observability)."""

    cancelled: bool = False
    """True when the turn stopped early because the cancellation token fired
    (e.g. voice barge-in). Distinct from ``error`` — cancelled turns are not
    failures, but post-turn work such as fact discovery must still be skipped."""

    hangup_requested: bool = False
    """True when the engine should end the session after finalizing the turn."""

    @property
    def succeeded(self) -> bool:
        """Test if the turn completed without error."""
        return self.error is None
